package com.notificationservice.presentation.controller;import com.notificationservice.application.port.in.NotificationUseCase;import com.notificationservice.presentation.response.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController@RequestMapping("/api/v1/notifications")public class NotificationController{private final NotificationUseCase useCase;public NotificationController(NotificationUseCase u){useCase=u;}@GetMapping public ApiResponse<List<NotificationResponse>>list(@AuthenticationPrincipal Jwt jwt,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.success(useCase.list(user(jwt),page,size).stream().map(NotificationResponse::from).toList());}@GetMapping("/unread-count")public ApiResponse<UnreadCountResponse>count(@AuthenticationPrincipal Jwt jwt){return ApiResponse.success(new UnreadCountResponse(useCase.unreadCount(user(jwt))));}@PostMapping("/{id}/read")public ApiResponse<NotificationResponse>read(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){return ApiResponse.success(NotificationResponse.from(useCase.markRead(user(jwt),id)));}@PostMapping("/read-all")public ApiResponse<Integer>readAll(@AuthenticationPrincipal Jwt jwt){return ApiResponse.success(useCase.markAllRead(user(jwt)));}private UUID user(Jwt jwt){return UUID.fromString(jwt.getSubject());}}
